INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (1,'Leadership & Strategy','Strategic Alignment','An organization plans to expand its operations, but FM continues using a maintenance strategy developed five years ago. What should the Facility Manager do FIRST?','["Increase the annual maintenance budget.", "Review organizational objectives and align the FM strategy.", "Replace outdated maintenance equipment.", "Outsource all maintenance activities."]','B','Align FM strategy with organizational goals.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (2,'Leadership & Strategy','Conflict Management','Two FM supervisors disagree about resource allocation, delaying critical maintenance activities. What is the BEST leadership response?','["Reassign one supervisor immediately.", "Escalate the disagreement to Human Resources.", "Issue formal warnings to both supervisors.", "Facilitate discussion, identify causes, and agree on a resolution."]','D','Resolve the underlying conflict through constructive engagement.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (3,'Leadership & Strategy','Change Management','Management introduces a new CAFM system, but technicians resist using it. What should the FM Manager do FIRST?','["Identify concerns, engage users, and develop a change-management plan.", "Require immediate use and penalize noncompliance.", "Cancel implementation until technicians agree.", "Assign all system activities to IT."]','A','Understand resistance and manage the transition.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (4,'Leadership & Strategy','Team Development','An FM department regularly misses performance targets because technicians lack skills required for modern building systems. What is the MOST appropriate action?','["Increase supervision during each maintenance shift.", "Replace technicians with specialist subcontractors.", "Conduct a competency gap assessment and implement targeted training.", "Reduce the complexity of assigned maintenance tasks."]','C','Identify skill gaps before selecting training solutions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (5,'Leadership & Strategy','Leadership During Budget Cuts','Senior management announces a 15% reduction in the FM operating budget while expecting service standards to remain unchanged. What should the FM Manager do FIRST?','["Reduce manpower across all facilities equally.", "Evaluate service priorities, risks, and efficiency opportunities.", "Postpone all preventive maintenance activities.", "Reduce service frequencies without informing stakeholders."]','B','Prioritize services using risk and business impact.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (51,'Leadership & Strategy','Executive Priorities','A new CEO wants the FM team to focus only on reducing expenditure, although critical sites have experienced rising outages. What should the FM leader present?','["An immediate equal cut across all maintenance budgets", "A proposal to eliminate all outsourced contracts", "A strategy connecting reliability risks, service outcomes, and cost", "A plan to postpone reporting until next year"]','C','Link resource decisions to organizational goals and material service risks.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (52,'Leadership & Strategy','Delegation and Accountability','A facility manager delegates fire-system inspections to a supervisor, who assumes the contractor is solely accountable. What is the BEST response?','["Clarify delegated responsibilities and retain management oversight", "Allow the contractor to define all acceptance criteria", "Remove inspection records from the FM reporting process", "Wait until an audit identifies a deficiency"]','A','Delegation of tasks does not remove the need for clear accountability and oversight.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (53,'Leadership & Strategy','Stakeholder Resistance','An office relocation is approved, but department heads oppose the new space plan because operational needs were not considered. What should the FM leader do NEXT?','["Proceed because the budget is approved", "Cancel all relocation activities permanently", "Ask security to enforce the relocation date", "Engage departments, validate needs, and reassess implementation impacts"]','D','Stakeholder engagement and change planning support adoption and service continuity.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (54,'Leadership & Strategy','Performance Coaching','A previously strong supervisor begins missing deadlines after a change in responsibilities. What is the MOST constructive first response?','["Issue a written warning immediately", "Discuss performance expectations, obstacles, and support needs", "Remove the supervisor from all responsibilities", "Transfer the problem to procurement"]','B','Coaching starts with understanding performance gaps and agreeing on improvements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (55,'Leadership & Strategy','FM Policy Change','A new regulatory requirement affects several facilities, but local teams apply inconsistent procedures. What should the FM director prioritize?','["Let each site interpret the requirement independently", "Stop all operations until every procedure is rewritten", "Set a consistent policy, communicate changes, and verify adoption", "Delegate the entire matter to the lowest-priced vendor"]','C','Consistent governance and communication enable compliant execution.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (6,'Facility Operations','PPM Effectiveness','Your FM contract reports 98% PPM completion, but critical equipment breakdowns continue increasing. What should you do FIRST?','["Increase the PPM completion target to 100%.", "Replace the existing maintenance subcontractor.", "Increase the number of technicians assigned.", "Analyze failure trends, asset criticality, and PPM effectiveness."]','D','Measure maintenance effectiveness, not just completion.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (7,'Facility Operations','Asset Management','During mobilization, the asset register contains several hundred assets without maintenance histories or verified condition information. What is the BEST approach?','["Validate the asset inventory and establish an asset-condition baseline.", "Accept the register and begin routine maintenance.", "Replace all assets with missing maintenance records.", "Ask Finance to determine the condition of each asset."]','A','A verified asset baseline supports informed maintenance decisions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (8,'Facility Operations','Work Order Prioritization','A CAFM system receives three requests simultaneously: a lobby light failure, a leaking pipe near electrical equipment, and a damaged office chair. Which action is MOST appropriate?','["Complete requests in the order received.", "Prioritize the lobby light because it is visible.", "Prioritize the leak due to immediate safety and operational risk.", "Assign equal priority to all three requests."]','C','Immediate safety risk takes priority.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (9,'Facility Operations','Maintenance Strategy','An AHU has experienced repeated failures despite following the manufacturer''s recommended PPM schedule. What should the FM Manager do NEXT?','["Continue the same schedule until the next annual review.", "Analyze failure causes and revise maintenance tasks as appropriate.", "Replace the AHU without further assessment.", "Increase inspection frequency for every asset in the facility."]','B','Use failure evidence to improve the maintenance strategy.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (10,'Facility Operations','Specialist Contractor Performance','A specialist contractor reports that corrective maintenance is complete, but the equipment fails during operational testing. What should the FM Manager do?','["Close the work order because repair activities were completed.", "Approve payment and record the failure as a new incident.", "Request the client to accept the equipment condition.", "Keep the work order open and require verified functional performance."]','D','Verify operational performance before closing the work order.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (56,'Facility Operations','Maintenance Backlog','A hospital''s noncritical maintenance backlog grows while technicians spend most time on repeated urgent calls. What should the FM manager do FIRST?','["Analyze backlog age, criticality, recurring faults, and resource capacity", "Delete old work orders to improve the KPI", "Suspend preventive maintenance for the next quarter", "Treat all work orders as emergencies"]','A','Prioritization requires understanding asset risk and the causes of workload pressure.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (57,'Facility Operations','Critical Spare Parts','A frequently failing pump has a long spare-part lead time and serves a critical process. What should the FM manager do?','["Purchase every available spare without analysis", "Wait for the next breakdown to confirm demand", "Transfer responsibility for stock to the client", "Set a critical-spares strategy using failure, lead-time, and consequence data"]','D','Spare holdings should reflect failure probability, lead time, and operational consequence.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (58,'Facility Operations','Work Order Closure','A technician closes an electrical corrective work order after replacing a component, but required test results were not recorded. What is the BEST action?','["Accept closure because the component is new", "Require test evidence and verify completion before final closure", "Create a second work order to avoid reopening the first", "Approve closure if the technician is experienced"]','B','Documented verification supports safe and reliable maintenance closure.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (59,'Facility Operations','Asset Criticality','A team proposes the same PPM frequency for all pumps despite very different operational consequences of failure. What should the FM manager recommend?','["Use the cheapest frequency for every pump", "Replace all pumps on the same date", "Set maintenance strategies based on criticality and asset requirements", "Leave the decision entirely to technicians"]','C','Asset criticality and technical needs should influence maintenance priorities.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (60,'Facility Operations','Service Transition','An incoming FM contractor discovers that emergency call-out contacts and isolation procedures are missing at takeover. What should happen before go-live?','["Verify critical procedures, responsibilities, and escalation arrangements", "Accept the gaps because they belong to the former contractor", "Remove emergency response from the initial service scope", "Delay documenting contacts until the first emergency"]','A','Critical operational readiness must be established before service commencement.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (11,'Risk Management','Business Continuity','A critical data center relies on one cooling system with no backup. What should the FM Manager prioritize?','["Assess business impact and develop an appropriate continuity solution.", "Increase housekeeping around the cooling equipment.", "Transfer maintenance responsibilities to another department.", "Wait until the system fails before approving backup equipment."]','A','Evaluate business consequences and continuity requirements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (12,'Risk Management','Risk Assessment','An FM team identifies multiple operational risks but has limited resources to address them. What should happen FIRST?','["Treat all risks as equally urgent.", "Transfer all identified risks to insurance providers.", "Assess likelihood and consequences to prioritize responses.", "Eliminate all activities associated with identified risks."]','C','Risk prioritization requires likelihood and impact assessment.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (13,'Risk Management','Emergency Preparedness','During an emergency drill, occupants struggle to locate designated assembly points. What is the BEST response?','["Cancel future drills to avoid confusion.", "Review findings and improve procedures, signage, and training.", "Replace the security team immediately.", "Inform occupants that the drill was only a simulation."]','B','Use drill findings to improve emergency readiness.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (14,'Risk Management','Risk Transfer','A contractor carries insurance covering damage caused by maintenance activities. During a repair, it damages critical equipment, causing operational disruption. What should the FM Manager recognize?','["Insurance eliminates all operational consequences.", "The contractor automatically assumes all FM responsibilities.", "The incident no longer requires risk management.", "Financial risk transfer does not eliminate operational disruption."]','D','Insurance does not eliminate service disruption.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (15,'Risk Management','Emergency Response','A major water leak threatens occupied areas and electrical installations. What should the FM Manager do FIRST?','["Activate emergency response procedures and protect occupants.", "Calculate the cost of replacing damaged equipment.", "Prepare a report for the next management meeting.", "Request quotations for permanent repairs."]','A','Life safety and incident control come before cost assessment.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (61,'Risk Management','Flood Exposure','A basement electrical room has flooded twice during seasonal storms. Which approach is BEST?','["Continue repairs without recording the hazard", "Rely solely on property insurance", "Relocate every electrical asset immediately without feasibility analysis", "Assess exposure and implement proportionate prevention and response measures"]','D','Risk treatment should address likelihood, consequence, and resilience.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (62,'Risk Management','Contractor Safety Risk','A contractor proposes hot work beside occupied storage areas without an approved permit. What should the FM manager do FIRST?','["Allow the task if the contractor promises to be careful", "Stop the activity and enforce permit and hazard controls", "Ask Finance whether the work is in budget", "Record the issue only after work is complete"]','B','High-risk work requires authorization and effective controls before proceeding.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (63,'Risk Management','Continuity Exercise','A business continuity exercise reveals that backup power operates, but critical staff cannot access emergency procedures. What should the FM manager do?','["Treat the exercise as successful because power worked", "Purchase another generator immediately", "Correct access and communication gaps, then retest the plan", "Cancel future exercises"]','C','Continuity effectiveness depends on people, procedures, and systems working together.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (64,'Risk Management','Risk Ownership','A risk register identifies elevator entrapment risk but no individual is assigned to monitor actions. What should the FM manager do?','["Assign a risk owner and define monitoring and response actions", "Close the risk because it has been documented", "Transfer the risk automatically to passengers", "Wait for an incident before naming an owner"]','A','Risk ownership enables follow-through and accountability.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (65,'Risk Management','Supply Chain Disruption','A sole-source controls supplier announces a likely six-month parts shortage. What is the BEST next step?','["Ignore the notice until a breakdown occurs", "Order a complete new BMS without assessment", "Stop all planned maintenance activities", "Assess affected critical assets and develop feasible supply contingencies"]','D','Evaluate exposure and feasible continuity responses before disruption occurs.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (16,'Finance & Business','Lifecycle Cost','Two chillers meet technical specifications. Chiller A has a lower purchase price but higher energy and maintenance costs; Chiller B costs more initially but has lower operating costs. How should FM evaluate them?','["Select the equipment with the lowest purchase price.", "Select the equipment with the longest warranty only.", "Compare total lifecycle costs over the evaluation period.", "Select the supplier offering the shortest delivery time."]','C','Lifecycle costing considers acquisition, operation, and maintenance costs.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (17,'Finance & Business','Budget Variance','Halfway through the financial year, the maintenance budget is 70% spent, although workload is broadly consistent with plan. What should the FM Manager do FIRST?','["Request an immediate 20% budget increase.", "Analyze actual costs, commitments, variances, and remaining forecast.", "Stop all corrective maintenance until next quarter.", "Transfer excess expenditure to the capital budget."]','B','Reliable forecasting starts with actuals, commitments, and remaining costs.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (18,'Finance & Business','Contracting Strategy','An organization considers comprehensive and non-comprehensive FM contracts for facilities with aging assets and incomplete maintenance records. What is the BEST initial approach?','["Choose comprehensive contracting to eliminate every risk.", "Choose non-comprehensive contracting because it is always cheaper.", "Award the contract to the lowest-priced provider.", "Assess asset condition, risk allocation, scope, and lifecycle cost."]','D','Contract choice should reflect asset condition, scope, and risk allocation.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (19,'Finance & Business','Procurement Evaluation','A supplier submits the lowest bid for replacement pumps but offers a shorter warranty and limited local technical support. What should the FM Manager recommend?','["Evaluate technical compliance, total cost, support, and procurement risks.", "Award immediately because the bid is lowest.", "Reject the bid solely because warranty is shorter.", "Split the purchase equally among all bidders."]','A','Evaluate overall value and risk, not only purchase price.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (20,'Finance & Business','Capital vs Operating Expenditure','An existing chiller requires frequent expensive repairs. Management asks whether it should be replaced. What should the FM Manager prepare?','["A list of repair invoices without further analysis.", "A recommendation based solely on equipment age.", "A repair-versus-replacement business case using lifecycle costs.", "A purchase order before obtaining budget approval."]','C','A business case supports evidence-based investment decisions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (66,'Finance & Business','Service Cost Benchmarking','Two comparable sites report very different maintenance cost per square meter. What should the FM manager do FIRST?','["Assume the higher-cost team is inefficient", "Normalize scope, condition, service levels, and cost data before comparing", "Reduce both site budgets by the same percentage", "Award both contracts to the cheaper provider"]','B','Meaningful benchmarks require comparable assumptions and service conditions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (67,'Finance & Business','Repair or Replace','A 15-year-old boiler needs an expensive overhaul, and management requests a recommendation. What is the BEST analysis?','["Compare only the initial replacement price", "Replace immediately because the boiler is old", "Evaluate lifecycle costs, condition, risk, and expected performance", "Keep repairing because capital approval takes time"]','C','Repair-replace decisions should be based on whole-life value and risk.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (68,'Finance & Business','Invoice Certification','A contractor submits an invoice for 100% PPM completion, but several mandatory inspection records are missing. What should the FM manager do?','["Verify contractual evidence and completed services before certification", "Approve payment because the invoice was submitted on time", "Deduct an arbitrary percentage without review", "Pay in full and ask for records next year"]','A','Certification must be supported by contractual deliverables and evidence.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (69,'Finance & Business','Unplanned Expenditure','A critical failure requires urgent expenditure outside the approved FM budget. What should the FM manager do?','["Charge the cost to an unrelated project", "Delay all safety actions until next year''s budget", "Split invoices to avoid approval thresholds", "Follow emergency authority rules, document necessity, and seek funding approval"]','D','Urgency requires controlled authorization, transparent records, and appropriate escalation.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (70,'Finance & Business','Outsourcing Decision','An organization is considering outsourcing a specialist system that its internal team rarely maintains. What is the BEST basis for the decision?','["Choose outsourcing because it always reduces cost", "Compare capability, risk, service outcomes, and total cost", "Retain in-house work solely to preserve headcount", "Choose the vendor with the most advertising"]','B','Sourcing decisions balance competence, performance, risk, and economics.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (21,'Sustainability','Energy Management','Electricity consumption has increased by 18% despite no significant change in facility occupancy. What should the FM Manager do FIRST?','["Replace all lighting fixtures immediately.", "Analyze energy consumption trends and investigate major loads.", "Reduce HVAC operating hours without assessing occupant needs.", "Request additional budget for electricity bills."]','B','Investigate consumption and significant energy loads.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (22,'Sustainability','Water Conservation','Water consumption rises unexpectedly, but no visible leaks are reported. What is the BEST action?','["Reduce water supply pressure across the entire facility.", "Replace every plumbing fixture.", "Accept the increase as normal seasonal consumption.", "Analyze metering data and investigate potential hidden leaks."]','D','Metering and investigation help locate unexplained consumption.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (23,'Sustainability','Waste Management','A facility generates substantial recyclable waste, but most materials are sent to landfill. What should the FM Manager implement?','["Assess waste streams and establish segregation and recycling measures.", "Increase waste collection frequency without changing the process.", "Stop collecting waste from low-occupancy areas.", "Focus only on reducing the waste contractor''s price."]','A','Understand waste streams before designing recycling measures.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (24,'Sustainability','Sustainability Performance','Management wants evidence that recent sustainability initiatives deliver results. What should the FM Manager establish?','["A report describing initiatives without measurements.", "A target to purchase only environmentally certified products.", "Baseline data, relevant KPIs, and regular performance monitoring.", "An annual awareness campaign without performance tracking."]','C','Baseline data and KPIs enable measurable improvement.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (25,'Sustainability','Occupant Wellness','Employees complain about indoor air quality and discomfort in several office areas. What should the FM Manager do FIRST?','["Reduce fresh-air intake to lower energy consumption.", "Investigate ventilation, environmental conditions, and occupant concerns.", "Replace the entire HVAC system immediately.", "Advise occupants that building meets original design."]','B','Investigate environmental conditions and occupant concerns.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (71,'Sustainability','HVAC Scheduling','An office building''s HVAC runs at full capacity on weekends despite minimal occupancy. What should the FM manager do?','["Switch all cooling off permanently", "Increase weekend cleaning to justify operation", "Review occupancy and controls, then optimize schedules while protecting requirements", "Replace the entire HVAC system immediately"]','C','Operating schedules should match actual demand and required environmental conditions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (72,'Sustainability','Water Baseline','A facility introduces low-flow fixtures and claims 25% water savings without adjusting for occupancy changes. What should the FM manager do?','["Normalize water data and compare against a defensible baseline", "Accept the claim because fixtures were installed", "Measure only the purchase cost of the fixtures", "Stop collecting water-meter data"]','A','Performance claims require credible baselines and comparable conditions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (73,'Sustainability','Waste Contractor','A waste contractor reports high recycling rates, but no weighbridge tickets or material breakdowns are provided. What is the BEST action?','["Accept the report because the contractor is certified", "Replace the contractor immediately without checking records", "Reduce waste collection frequencies", "Request traceable evidence and verify reported waste performance"]','D','Sustainability reporting needs reliable, verifiable data.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (74,'Sustainability','Energy Retrofit','A proposed LED retrofit offers energy savings but disrupts an occupied clinical area during installation. What should the FM manager recommend?','["Cancel the energy initiative permanently", "Assess lifecycle benefits and coordinate a safe, phased implementation", "Install immediately during normal operations", "Select lighting solely by lowest unit price"]','B','Sustainability initiatives must also protect operations and occupant needs.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (75,'Sustainability','Green Procurement','Two cleaning products have similar purchase prices, but one generates more packaging waste and requires hazardous handling. What should the FM manager do?','["Select whichever supplier delivers first", "Ignore disposal and handling costs", "Assess environmental, safety, performance, and lifecycle considerations", "Select the product with the brightest packaging"]','C','Responsible procurement considers whole-life impacts, not only price.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (26,'Communication','Stakeholder Communication','An FM team frequently receives conflicting instructions from different client representatives. What is the BEST solution?','["Follow whichever instruction is received first.", "Allow technicians to decide which representative has authority.", "Reject all client instructions until contract renewal.", "Establish agreed communication channels and decision authorities."]','D','Defined communication authority reduces conflicting instructions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (27,'Communication','Incident Communication','A critical AHU fails in a hospital, affecting a sensitive operational area. The technical team is investigating. What should the FM Manager communicate?','["Confirmed facts, immediate impacts, actions underway, and update arrangements.", "A guaranteed repair completion time before diagnosis.", "Only the name of the technician assigned to repair.", "Nothing until equipment is fully restored."]','A','Provide accurate, timely, actionable incident information.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (28,'Communication','Communication Effectiveness','The FM Manager sends detailed technical reports to senior executives, but decisions are delayed because reports are difficult to interpret. What should change?','["Include more technical data in every report.", "Stop submitting technical reports altogether.", "Present concise findings, business impacts, risks, and required decisions.", "Delegate all management communication to the contractor."]','C','Executive reporting should support decisions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (29,'Communication','Client Complaints','The client complains about repeated maintenance delays, while FM insists contractual response-time KPIs are achieved. What should the FM Manager do FIRST?','["Explain that meeting KPIs means complaints are invalid.", "Engage client to clarify expectations and investigate service outcomes.", "Increase KPI targets without examining current performance.", "Ask client to submit fewer maintenance requests."]','B','Service outcomes and stakeholder expectations both matter.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (30,'Communication','Communication Planning','A new multi-facility contract involves client, subcontractors, engineers, security, and occupants. What should the FM Manager establish during mobilization?','["A single communication channel for every stakeholder.", "A requirement that all communications go through technicians.", "An informal process based on previous contracts.", "A communication plan defining information, recipients, timing, and responsibilities."]','D','Communication planning defines who needs what information and when.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (76,'Communication','Emergency Status Updates','During a power outage, management receives conflicting restoration estimates from multiple teams. What should the FM manager establish?','["A single verified update process with clear ownership and timing", "Allow each technician to communicate estimates directly", "Stop all updates until the outage is over", "Provide a fixed restoration promise without technical confirmation"]','A','Controlled, accurate updates maintain stakeholder trust.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (77,'Communication','Difficult Client Meeting','A client is angry about recurring elevator outages and demands that the contractor be terminated immediately. What should the FM manager do FIRST?','["Agree to terminate before reviewing evidence", "Defend the contractor without hearing the complaint", "Close the complaint because repair KPIs were achieved", "Acknowledge concerns, establish facts, and agree on an action review"]','D','Active listening and fact-based response support constructive resolution.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (78,'Communication','Technical to Executive','Senior management asks why a building upgrade is necessary, but the engineering report uses only technical terminology. What should the FM manager do?','["Submit the same report with more technical appendices", "Explain risk, business impact, alternatives, and investment implications", "Ask executives to interpret the technical report themselves", "Avoid discussing cost until after approval"]','B','Tailor communication to the audience''s decisions and priorities.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (79,'Communication','Shift Handover','Recurring faults are missed between day and night shifts because handovers are verbal and inconsistent. What is the BEST improvement?','["Increase the length of every shift", "Eliminate night-shift reporting", "Introduce structured logs, ownership, and acknowledgment of critical issues", "Allow each shift to keep private notes"]','C','Structured communication reduces loss of operational information.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (80,'Communication','RACI Confusion','A specialist contractor completes PPM, but the engineer and QA/QC team each assume the other must certify the work. What should the FM manager do?','["Define responsible, accountable, consulted, and informed roles for approval steps", "Ask the contractor to certify its own work without oversight", "Remove the approval stage from the process", "Wait until the next contract renewal"]','A','A RACI matrix clarifies roles and decision ownership.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (31,'Quality','PPM Verification','A subcontractor reports 100% PPM completion with signed checklists and photographs. During final inspection, FM discovers unmaintained assets and reused photographs. What should happen FIRST?','["Suspend affected certification and investigate discrepancies.", "Terminate the subcontractor immediately.", "Dismiss engineers who signed checklists.", "Accept reports because they were already certified."]','A','Preserve evidence and investigate before deciding remedies.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (32,'Quality','Quality Assurance vs Quality Control','A QA checklist omits an important requirement from an approved method statement. QC inspections are completed using the checklist, but non-compliant installations are later found. What should FM prioritize?','["Continue inspections using the same checklist.", "Accept installations because QC records were signed.", "Assess the nonconformity and correct the deficient quality-control process.", "Remove the entire QA/QC team before investigating."]','C','Address both nonconformity and deficient control process.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (33,'Quality','Continuous Improvement','A facility repeatedly experiences the same plumbing failures despite several temporary repairs. What is the BEST quality improvement approach?','["Increase the number of emergency work orders.", "Conduct root-cause analysis and implement sustainable corrective action.", "Replace the plumbing subcontractor without assessing failures.", "Reduce reporting of repeated incidents."]','B','Root-cause analysis supports lasting corrective action.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (34,'Quality','Quality Performance','An FM contract achieves high PPM completion rates, but occupant satisfaction remains low. What should the FM Manager do?','["Continue reporting only PPM completion rates.", "Remove customer satisfaction from reports.", "Increase PPM targets without reviewing service quality.", "Evaluate whether quality measures reflect actual service outcomes."]','D','Quality measures should reflect actual service performance.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (35,'Quality','Quality Audit','An internal audit identifies recurring failures to follow approved maintenance procedures. What is the MOST effective response?','["Record nonconformities, investigate causes, and verify corrective actions.", "Close audit because procedures already exist.", "Issue warnings without examining process weaknesses.", "Stop future audits until performance improves."]','A','Effective audits lead to verified corrective improvements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (81,'Quality','Repeated NCRs','Three audits identify the same failure to record water-treatment readings, even after staff received reminders. What should the FM manager do?','["Send the same reminder for a fourth time", "Remove the readings from the procedure", "Close the findings because staff were informed", "Investigate systemic causes and verify effectiveness of corrective action"]','D','Repeated nonconformities require root-cause and effectiveness checks.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (82,'Quality','Inspection Sampling','A contractor requests acceptance of hundreds of identical fixtures based on one photograph. What should the FM manager do?','["Accept the entire batch based on the photograph", "Apply an appropriate inspection and evidence plan against requirements", "Reject every fixture without inspection", "Waive all checks to meet the schedule"]','B','Inspection evidence must be appropriate to the scope and acceptance criteria.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (83,'Quality','Customer Satisfaction','A cleaning contractor meets scheduled visit frequencies, but occupants repeatedly report poor restroom hygiene. What should the FM manager prioritize?','["Increase visit frequency without inspection", "Ignore complaints because schedules were met", "Assess cleaning outcomes and adjust controls and service measures", "Change the report format without changing service"]','C','Quality concerns service outcomes, not merely activity completion.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (84,'Quality','Document Control','Technicians use an outdated maintenance procedure after a new approved version was issued. What should the FM manager do?','["Control document versions, withdraw obsolete copies, and confirm training", "Allow both versions until annual audit", "Delete the maintenance history", "Ask technicians to choose their preferred procedure"]','A','Effective document control ensures teams use current approved instructions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (85,'Quality','Supplier Improvement','A specialist vendor meets response times but repeatedly installs replacement components that fail early. What is the BEST action?','["Reward the vendor for fast attendance", "Measure only the number of work orders closed", "Replace all equipment across the site", "Analyze component failures, specifications, and vendor corrective actions"]','D','Supplier quality should be assessed using reliability and verified corrective improvement.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (36,'Real Estate','Space Planning','An organization expects its workforce to grow by 25% over three years. Existing office space is nearly fully occupied. What should FM do FIRST?','["Lease additional space immediately.", "Convert meeting rooms into permanent offices.", "Assess future functional needs, occupancy, and space options.", "Relocate the entire organization."]','C','Future space needs should be established before selecting premises.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (37,'Real Estate','Real Estate Decision','Management is deciding whether to renew an existing office lease or relocate. What should guide the recommendation?','["Rental cost alone.", "Total occupancy cost, location, functional needs, and business objectives.", "The FM Manager''s personal preference.", "The newest available office building."]','B','Real estate decisions must reflect total cost and business fit.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (38,'Real Estate','Functional Programming','A government organization plans a new customer service center. What should FM help define before detailed design?','["Final furniture supplier.", "Preferred paint colors.", "Maintenance contractor''s invoice format.", "User activities, space requirements, relationships, and operational needs."]','D','Functional programming translates user needs into space requirements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (39,'Real Estate','Space Utilization','A building appears fully allocated, but surveys show many workstations remain unused throughout the week. What is the BEST response?','["Analyze utilization patterns before recommending space changes.", "Lease more space to accommodate future demand.", "Remove all unused workstations immediately.", "Reduce cleaning frequency across the building."]','A','Utilization evidence should inform space decisions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (40,'Real Estate','Real Estate Portfolio','An organization operates facilities with differing occupancy costs, conditions, and utilization rates. Management asks which sites should be retained. What should FM do?','["Recommend closing the oldest buildings first.", "Retain only facilities with lowest rental costs.", "Compare portfolio performance against organizational requirements and lifecycle costs.", "Transfer all real estate decisions to the maintenance contractor."]','C','Portfolio decisions require comparative business and financial analysis.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (86,'Real Estate','Lease Renewal Timing','A lease expires in 14 months, and the business expects a new hybrid-work policy. What should the FM manager do?','["Renew immediately for the maximum term", "Develop demand scenarios and compare lease and space options early", "Wait until the final month to discuss options", "Assume the current occupancy rate will never change"]','B','Early planning allows real estate decisions to reflect future business demand.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (87,'Real Estate','Accessibility Needs','A proposed office layout meets the space budget but limits accessible routes to shared facilities. What should the FM manager do?','["Approve because the total area meets the budget", "Ask affected occupants to use another building", "Reassess functional requirements and applicable accessibility obligations", "Postpone accessibility issues until occupation"]','C','Functional planning must consider safe, inclusive access and requirements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (88,'Real Estate','Consolidation Study','Management proposes closing one of three offices to save rent. What should the FM manager assess FIRST?','["Capacity, location, service needs, transition cost, and business impact", "Close the site with the oldest furniture", "Move all staff into the lowest-rent building immediately", "Compare rent only, excluding relocation costs"]','A','Consolidation requires total occupancy and operational impact analysis.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (89,'Real Estate','Future Flexibility','A company expects uncertain headcount changes and asks how to design a new workplace. What is the BEST recommendation?','["Fix every workstation permanently", "Maximize private offices without demand analysis", "Design solely around today''s headcount", "Develop flexible space scenarios linked to changing functional needs"]','D','Flexible planning reduces exposure to uncertain demand.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (90,'Real Estate','Portfolio Data','A property portfolio contains inconsistent floor-area definitions, making occupancy-cost comparisons unreliable. What should the FM manager do?','["Rank facilities using the inconsistent figures", "Standardize measurement definitions and validate portfolio data", "Ignore the inconsistency because all buildings are occupied", "Replace every property manager"]','B','Comparable real estate decisions depend on consistent measurement and data.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (41,'Facility Technology & Data Management','CAFM Data Quality','A new CAFM system contains duplicate asset records, missing locations, and inconsistent equipment classifications. What should FM do FIRST?','["Generate reports using existing records.", "Establish data governance and validate asset information.", "Replace CAFM software immediately.", "Ask technicians to ignore duplicate records."]','B','Accurate, governed data is essential for reliable CAFM outputs.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (42,'Facility Technology & Data Management','Technology Investment','Management proposes installing IoT sensors across all facilities to reduce maintenance costs. What should FM evaluate FIRST?','["Number of sensors available from suppliers.", "Visual appearance of monitoring dashboard.", "Lowest installation quotation.", "Business objectives, expected benefits, data requirements, and integration needs."]','D','Technology selection should follow business and information needs.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (43,'Facility Technology & Data Management','Cybersecurity','A maintenance subcontractor requests unrestricted remote access to the Building Management System (BMS). What is the BEST response?','["Coordinate with IT/security to provide approved, controlled, least-privilege access.", "Grant unrestricted access to accelerate maintenance.", "Share the FM Manager''s login credentials.", "Disable system security controls during maintenance."]','A','Remote access must follow approved cybersecurity controls.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (44,'Facility Technology & Data Management','Data-Driven Decisions','A CAFM dashboard shows increasing corrective maintenance costs but does not identify which assets are responsible. What should FM do?','["Reduce maintenance budget immediately.", "Stop recording minor corrective maintenance work orders.", "Improve asset-level data analysis to identify major cost drivers.", "Replace CAFM system before investigating."]','C','Asset-level data reveals maintenance cost drivers.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (45,'Facility Technology & Data Management','Information Management','During contractor transition, outgoing contractor provides asset records in multiple inconsistent formats. What should incoming FM prioritize?','["Delete historical records and create entirely new register.", "Validate, standardize, and securely transfer required asset information.", "Accept records without checking completeness.", "Restrict asset information to outgoing contractor."]','B','Standardized, validated records support reliable transition.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (91,'Facility Technology & Data Management','Predictive Analytics','A vendor offers AI-based failure prediction, but the facility has only a few months of incomplete work-order data. What should the FM manager do?','["Buy the software immediately because it uses AI", "Delete historical data and start over", "Assess data quality, use cases, and readiness before investing", "Assume predictions will be accurate without validation"]','C','Technology value depends on suitable data and a defined use case.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (92,'Facility Technology & Data Management','BMS Alarm Overload','Operators receive hundreds of nuisance BMS alarms daily and sometimes miss critical alerts. What should the FM manager do?','["Review alarm priorities, thresholds, ownership, and response processes", "Disable all BMS alarms indefinitely", "Increase alarm volume to ensure attention", "Transfer alarm handling to an untrained team"]','A','Alarm rationalization supports timely recognition of critical conditions.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (93,'Facility Technology & Data Management','Data Sharing','A vendor requests the full asset database, including sensitive security system details, for a limited maintenance assignment. What is the BEST response?','["Provide everything because the vendor has a contract", "Publish the database on a shared public drive", "Email administrator passwords with the asset file", "Apply approved data classification and share only authorized necessary information"]','D','Information sharing should be controlled and proportionate to legitimate need.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (94,'Facility Technology & Data Management','System Integration','A new CAFM system cannot exchange work-order status with the existing helpdesk, creating duplicate entries. What should the FM manager do?','["Require users to maintain duplicate records indefinitely", "Assess interface requirements, data ownership, and integration options", "Remove work-order tracking from the helpdesk", "Replace both systems before studying the problem"]','B','System integration should be driven by workflows and data requirements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (95,'Facility Technology & Data Management','KPI Integrity','A dashboard reports 99% on-time CM completion, but technicians routinely enter incorrect closure timestamps. What should the FM manager do?','["Publish the KPI without qualification", "Raise the KPI target to 100%", "Validate timestamp controls and correct data-entry governance", "Stop reporting CM performance permanently"]','C','Reliable management decisions require trustworthy source data.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (46,'Project Management','Project Planning','An organization plans to replace several critical AHUs while the building remains occupied. What should FM establish before execution?','["Purchase order without reviewing operational constraints.", "Schedule based only on equipment delivery dates.", "Instruction to shut down all systems simultaneously.", "Coordinated execution plan covering scope, shutdowns, risks, and stakeholders."]','D','Plan scope, operational constraints, risks, and coordination before execution.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (47,'Project Management','Project Change','During an FM refurbishment project, client requests additional works outside approved scope. What should PM do FIRST?','["Document and assess change''s cost, schedule, and operational impacts.", "Instruct contractor to proceed immediately.", "Reject request without assessing implications.", "Include additional cost in final invoice without approval."]','A','Assess changes before seeking authorization and implementation.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (48,'Project Management','Project Performance','A project is 60% complete, but actual expenditure reached 80% of approved budget. Management requests a cost forecast. What should PM do?','["Assume remaining 40% costs only 20% of budget.", "Reduce scope without formal approval.", "Validate actual costs, assess remaining work, and prepare Estimate at Completion.", "Continue execution and review budget at closeout."]','C','EAC forecasting requires reliable actual and remaining-cost estimates.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (49,'Project Management','Project Handover','A new facility system is installed and operational, but maintenance manuals, training records, and as-built drawings are incomplete. What is BEST?','["Close project because system operates correctly.", "Track outstanding deliverables and apply agreed handover acceptance requirements.", "Transfer incomplete documents to maintenance contractor without review.", "Approve final completion and request documents later."]','B','Apply agreed acceptance requirements and manage incomplete deliverables.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (50,'Project Management','Project Closeout','An FM improvement project achieved technical objectives, but management wants assurance expected operational benefits will continue. What should PM do?','["Close project immediately after final invoice.", "Release all personnel without transition arrangements.", "Transfer responsibility to Finance without performance measures.", "Confirm operational ownership, performance measures, and benefits monitoring."]','D','Benefits need ownership and measurement after delivery.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (96,'Project Management','Occupied Building Works','A refurbishment contractor proposes noisy demolition during occupied office hours to shorten the schedule. What should the project manager do FIRST?','["Assess occupant impact, constraints, and safe sequencing alternatives", "Approve because a shorter schedule always reduces cost", "Stop the entire project indefinitely", "Ask occupants to accept any level of disruption"]','A','Execution planning must account for operations, safety, and stakeholders.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (97,'Project Management','Critical Path Recovery','A facility upgrade is behind schedule, and management proposes adding ten workers immediately. What should the project manager do?','["Add workers before reviewing dependencies", "Change the baseline to hide delay", "Reduce testing time without approval", "Analyze critical-path constraints and evaluate recovery options"]','D','Recovery actions should target actual schedule drivers.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (98,'Project Management','Variation Control','A contractor claims a verbal client instruction authorizes additional work and payment. No approved change record exists. What should the project manager do?','["Approve payment based only on the contractor''s account", "Verify instructions, entitlement, and formal change authorization", "Ignore the claim without investigation", "Charge the cost to another project"]','B','Change control requires documented scope and authority assessment.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (99,'Project Management','Commissioning Failure','A new fire pump fails its acceptance test shortly before planned handover. What should the project manager do?','["Issue final acceptance because installation is complete", "Transfer the defect without informing operations", "Record the defect, correct it, and repeat required acceptance testing", "Remove the test result from the completion file"]','C','Handover depends on demonstrated compliance with acceptance requirements.');
INSERT OR REPLACE INTO questions (id,domain,title,question,options,answer,explanation) VALUES (100,'Project Management','Lessons Learned','A multi-site retrofit finishes successfully, but several sites experienced the same avoidable access delays. What should the project manager do at closeout?','["Capture causes, actions, and reusable lessons for future projects", "Close all records because the final result was successful", "Attribute every delay to the contractor without review", "Delete the schedule logs to simplify archiving"]','A','Closeout should preserve learning for future delivery.');
